// @ts-check
import { execFileSync } from 'node:child_process';
import { defineConfig } from 'astro/config';
import node from '@astrojs/node';

/**
 * Public-safe revision label (P1-M1-E1.1, spec §Scope of Work item 2).
 *
 * Resolution order:
 *   1. PANCHEW_REVISION, if it is public-safe.
 *   2. The short commit hash of HEAD, if this is a git checkout.
 *   3. The package version.
 *
 * Every candidate is validated against the public-safe label rule before it is
 * accepted, so an untrusted environment value can never widen the public
 * surface. The label exposes no secret, no absolute path, and no environment
 * detail.
 *
 * @type {RegExp}
 */
const PUBLIC_SAFE_LABEL = /^[A-Za-z0-9._-]{1,64}$/;

/** @param {string | undefined} candidate */
const publicSafe = (candidate) =>
  typeof candidate === 'string' && PUBLIC_SAFE_LABEL.test(candidate) ? candidate : undefined;

function resolveRevision() {
  const fromEnv = publicSafe(process.env.PANCHEW_REVISION?.trim());
  if (fromEnv) return fromEnv;

  try {
    const sha = execFileSync('git', ['rev-parse', '--short=12', 'HEAD'], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
    const fromGit = publicSafe(sha);
    if (fromGit) return fromGit;
  } catch {
    // Not a git checkout (for example an exported source archive). Fall through.
  }

  return '0.1.0';
}

// https://astro.build/config
export default defineConfig({
  // D2: on-demand server rendering for every route, served by a Node HTTP
  // process. Required so that M3 can hold a server-side secret (D4).
  output: 'server',
  adapter: node({ mode: 'standalone' }),

  // Keep the served document self-contained: no separate stylesheet request,
  // and therefore no build-asset path in the public surface.
  build: { inlineStylesheets: 'always' },

  // No client-side runtime, no dev toolbar, no telemetry surface in the output.
  devToolbar: { enabled: false },

  vite: {
    define: {
      __PANCHEW_REVISION__: JSON.stringify(resolveRevision()),
    },
  },
});

