/**
 * Shared harness for starting the built baseline server.
 *
 * Used by the correctness suite and by the accessibility, security, and
 * performance checks so that every check exercises the same artefact
 * (`dist/server/entry.mjs`) produced by `npm run build`.
 *
 * Every failure path throws. Callers are expected to let the error propagate so
 * the owning command exits non-zero (fail-closed).
 */
import { spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import net from 'node:net';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setTimeout as delay } from 'node:timers/promises';

export const REPO_ROOT = path.resolve(fileURLToPath(new URL('../..', import.meta.url)));
export const SERVER_ENTRY = path.join(REPO_ROOT, 'dist', 'server', 'entry.mjs');

/** Fixed probe cadence for readiness/cold-start measurement (ms). */
export const PROBE_INTERVAL_MS = 100;

/** Reserve an ephemeral port from the OS and release it for the child to bind. */
export async function findFreePort() {
  return await new Promise((resolve, reject) => {
    const server = net.createServer();
    server.unref();
    server.on('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const { port } = server.address();
      server.close((err) => (err ? reject(err) : resolve(port)));
    });
  });
}

export function assertBuilt() {
  if (!existsSync(SERVER_ENTRY)) {
    throw new Error(
      `Build artefact not found at dist/server/entry.mjs. Run \`npm run build\` first.`,
    );
  }
}

async function probeHealth(url, timeoutMs) {
  try {
    const res = await fetch(`${url}/health`, { signal: AbortSignal.timeout(timeoutMs) });
    // Drain so the socket is released promptly.
    await res.arrayBuffer();
    return res.status;
  } catch {
    return null;
  }
}

/**
 * Start the built baseline and wait until `GET /health` first answers 200.
 *
 * @param {object} [options]
 * @param {NodeJS.ProcessEnv} [options.env] Full environment for the child. When
 *   provided it REPLACES the inherited environment (used by the secret-hygiene
 *   check to run in a sanitised environment).
 * @param {number} [options.readyTimeoutMs] Fail-closed ceiling for readiness.
 * @returns {Promise<{url: string, port: number, child: import('node:child_process').ChildProcess, readyMs: number, stop: () => Promise<void>}>}
 */
export async function startBaseline(options = {}) {
  const { env, readyTimeoutMs = 30_000 } = options;
  assertBuilt();

  const port = options.port ?? (await findFreePort());
  const host = '127.0.0.1';
  const url = `http://${host}:${port}`;

  const childEnv = { ...(env ?? process.env), HOST: host, PORT: String(port) };

  // Monotonic origin: taken immediately before process launch.
  const t0 = process.hrtime.bigint();
  const child = spawn(process.execPath, [SERVER_ENTRY], {
    cwd: REPO_ROOT,
    env: childEnv,
    stdio: ['ignore', 'pipe', 'pipe'],
  });

  let exited = null;
  child.on('exit', (code, signal) => {
    exited = { code, signal };
  });
  let stderr = '';
  child.stderr.on('data', (chunk) => {
    stderr += chunk.toString();
  });
  child.stdout.resume();

  const deadline = Date.now() + readyTimeoutMs;
  let readyMs = null;
  while (Date.now() < deadline) {
    if (exited) {
      throw new Error(
        `Baseline server exited before becoming ready (code=${exited.code} signal=${exited.signal}).\n${stderr}`,
      );
    }
    const status = await probeHealth(url, PROBE_INTERVAL_MS * 20);
    if (status === 200) {
      readyMs = Number(process.hrtime.bigint() - t0) / 1e6;
      break;
    }
    await delay(PROBE_INTERVAL_MS);
  }

  const stop = async () => {
    if (exited) return;
    await new Promise((resolve) => {
      child.once('exit', resolve);
      child.kill('SIGTERM');
      setTimeout(() => child.kill('SIGKILL'), 5_000).unref();
    });
  };

  if (readyMs === null) {
    await stop();
    throw new Error(
      `Baseline server did not answer GET /health with 200 within ${readyTimeoutMs} ms.\n${stderr}`,
    );
  }

  return { url, port, child, readyMs, stop };
}

/** Media type of a Content-Type header, lowercased, parameters stripped. */
export function mediaType(contentTypeHeader) {
  return String(contentTypeHeader ?? '')
    .split(';')[0]
    .trim()
    .toLowerCase();
}

