/**
 * Correctness suite for the P1-M1-E1.1 baseline.
 *
 * Scope: the baseline routes, exercised over HTTP against the built artefact
 * (`dist/server/entry.mjs`). Assertions are exactly those fixed by the Epic
 * spec §Scope of Work item 4 (Correctness), plus structural assertions that
 * enforce the closed route surface (D2) and the M3 prohibition (D4).
 *
 * Fail-closed: `vitest run` exits non-zero on any failure.
 */
import { readdirSync, existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
// @ts-expect-error - plain ESM helper shared with the check scripts
import { REPO_ROOT, mediaType, startBaseline } from '../scripts/lib/server.mjs';

let server: { url: string; stop: () => Promise<void> };

beforeAll(async () => {
  server = await startBaseline();
});

afterAll(async () => {
  await server?.stop();
});

describe('GET /health', () => {
  it('returns 200, application/json, and exactly {"status":"ok"}', async () => {
    const res = await fetch(`${server.url}/health`);
    const body = await res.text();

    expect(res.status).toBe(200);
    expect(mediaType(res.headers.get('content-type'))).toBe('application/json');
    expect(body).toBe('{"status":"ok"}');
    expect(JSON.parse(body)).toEqual({ status: 'ok' });
  });
});

describe('GET /revision', () => {
  it('returns 200, application/json, and a body with a single revision string field', async () => {
